def load_source(path: Path) -> dict[str, Any]:
    """Validate original nested SQuAD data and its reference answer spans."""
    data = json.loads(path.read_text(encoding="utf-8"))
    if not isinstance(data, dict) or data.get("version") != "v2.0":
        raise ValueError("Expected SQuAD version v2.0")
    articles = data.get("data")
    if not isinstance(articles, list) or not articles:
        raise ValueError("Expected a non-empty SQuAD data list")
    seen: set[str] = set()
    for article in articles:
        if (
            not isinstance(article, dict)
            or not isinstance(article.get("title"), str)
            or not article["title"].strip()
        ):
            raise ValueError("Each article needs a non-empty title")
        paragraphs = article.get("paragraphs")
        if not isinstance(paragraphs, list) or not paragraphs:
            raise ValueError("Each article needs paragraphs")
        for paragraph in paragraphs:
            if (
                not isinstance(paragraph, dict)
                or not isinstance(paragraph.get("context"), str)
                or not paragraph["context"].strip()
            ):
                raise ValueError("Each paragraph needs non-empty context")
            qas = paragraph.get("qas")
            if not isinstance(qas, list):
                raise TypeError("Each paragraph needs a qas list")
            for qa in qas:
                if not isinstance(qa, dict):
                    raise TypeError("Each question must be an object")
                for field in ("id", "question"):
                    if not isinstance(qa.get(field), str) or not qa[field].strip():
                        raise ValueError(f"Question needs non-empty {field}")
                if qa["id"] in seen:
                    raise ValueError(f"Duplicate question ID: {qa['id']}")
                seen.add(qa["id"])
                if not isinstance(qa.get("is_impossible"), bool):
                    raise TypeError(f"Question {qa['id']} needs boolean is_impossible")
                answers = qa.get("answers")
                if (
                    not isinstance(answers, list)
                    or bool(answers) == qa["is_impossible"]
                ):
                    raise ValueError(f"Inconsistent answers for {qa['id']}")
                for answer in answers:
                    if not isinstance(answer, dict):
                        raise TypeError(f"Invalid answer for {qa['id']}")
                    text, start = answer.get("text"), answer.get("answer_start")
                    if (
                        not isinstance(text, str)
                        or not text
                        or type(start) is not int
                        or start < 0
                        or paragraph["context"][start : start + len(text)] != text
                    ):
                        raise ValueError(f"Invalid answer offset/text for {qa['id']}")
    return data


def download_source(cache: Path) -> Path:
    """Download only the official public dataset, publishing a validated cache."""
    if cache.exists():
        load_source(cache)
        return cache
    cache.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.TemporaryDirectory(
        prefix=".squad-download-", dir=cache.parent
    ) as temp:
        candidate = Path(temp) / "dev-v2.0.json"
        with (
            urlopen(SOURCE_URL, timeout=60) as response,
            candidate.open("wb") as target,
        ):
            while block := response.read(64 * 1024):
                target.write(block)
        load_source(candidate)
        candidate.rename(cache)
    return cache


def passage_id(text: str) -> str:
    """Identify identical passage text consistently across questions and titles."""
    return hashlib.sha256(text.encode("utf-8")).hexdigest()


def select_cases(
    candidates: list[dict[str, Any]], count: int, rng: random.Random
) -> list[dict[str, Any]]:
    """Select reproducibly across article titles rather than one article first."""
    groups: dict[str, deque[dict[str, Any]]] = {}
    by_title: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for case in sorted(candidates, key=lambda case: case["id"]):
        by_title[case["title"]].append(case)
    titles = sorted(by_title)
    rng.shuffle(titles)
    for title in titles:
        rng.shuffle(by_title[title])
        groups[title] = deque(by_title[title])
    chosen: list[dict[str, Any]] = []
    while len(chosen) < count:
        progressed = False
        for title in titles:
            if groups[title]:
                chosen.append(groups[title].popleft())
                progressed = True
                if len(chosen) == count:
                    break
        if not progressed:
            raise ValueError(f"Need {count} cases, found only {len(chosen)}")
    return chosen


def prepare(source: Path, output: Path, seed: int = DEFAULT_SEED) -> dict[str, Any]:
    """Write separated evidence and evaluation data without overwriting outputs."""
    if output.exists():
        raise FileExistsError(f"Output already exists; choose another folder: {output}")
    data = load_source(source)
    passages: dict[str, dict[str, str]] = {}
    candidates: list[dict[str, Any]] = []
    for article in sorted(data["data"], key=lambda article: article["title"]):
        for paragraph in article["paragraphs"]:
            pid = passage_id(paragraph["context"])
            passages.setdefault(
                pid, {"title": article["title"], "text": paragraph["context"]}
            )
            for qa in paragraph["qas"]:
                candidates.append(
                    {
                        "id": qa["id"],
                        "question": qa["question"],
                        "title": article["title"],
                        "passage_id": pid,
                        "is_impossible": qa["is_impossible"],
                        "answers": qa["answers"],
                        "review_status": "needs_review"
                        if qa["is_impossible"]
                        else "not_reviewed",
                    }
                )
    rng = random.Random(seed)
    selected = select_cases([q for q in candidates if not q["is_impossible"]], 20, rng)
    selected += select_cases([q for q in candidates if q["is_impossible"]], 10, rng)
    selected_ids = {case["passage_id"] for case in selected}
    extra = sorted(set(passages) - selected_ids)
    if len(extra) < 10:
        raise ValueError(f"Need 10 additional passages, found only {len(extra)}")
    rng.shuffle(extra)
    corpus_ids = sorted(selected_ids | set(extra[:10]))
    manifest = {
        "dataset": "SQuAD 2.0",
        "split": "dev",
        "source_url": SOURCE_URL,
        "license_url": LICENSE_URL,
        "attribution": "SQuAD 2.0, Rajpurkar et al.; source passages derived from Wikipedia.",
        "source_sha256": hashlib.sha256(source.read_bytes()).hexdigest(),
        "seed": seed,
        "recipe_version": 1,
        "requested": {
            "answerable": 20,
            "unanswerable_candidates": 10,
            "extra_passages": 10,
        },
        "actual": {
            "answerable": 20,
            "unanswerable_candidates": 10,
            "extra_passages": 10,
            "unique_passages": len(corpus_ids),
        },
        "question_ids": [case["id"] for case in selected],
        "passages": [
            {
                "id": pid,
                "title": passages[pid]["title"],
                "file": f"corpus/{pid}.md",
                "role": "selected_source" if pid in selected_ids else "extra",
            }
            for pid in corpus_ids
        ],
        "review_note": "Unanswerable candidates require review against the entire corpus.",
    }
    output.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.TemporaryDirectory(
        prefix=".squad-output-", dir=output.parent
    ) as temp:
        staging = Path(temp) / "dataset"
        corpus = staging / "corpus"
        corpus.mkdir(parents=True)
        for pid in corpus_ids:
            passage = passages[pid]
            (corpus / f"{pid}.md").write_text(
                f"# {passage['title']}\n\n{passage['text']}\n",
                encoding="utf-8",
                newline="\n",
            )
        (staging / "cases.jsonl").write_text(
            "".join(
                json.dumps(case, ensure_ascii=False, sort_keys=True) + "\n"
                for case in selected
            ),
            encoding="utf-8",
            newline="\n",
        )
        (staging / "manifest.json").write_text(
            json.dumps(manifest, ensure_ascii=False, indent=2, sort_keys=True) + "\n",
            encoding="utf-8",
            newline="\n",
        )
        staging.rename(output)
    return manifest


